mapper.select:
SELECT 
FROM trade_refund r
JOIN trade_order o ON o.order_id = r.order_id
WHERE r.refund_id = #{refundId}
AND o.tenant_id = #{tenantId}

SELECT 
FROM trade_refund r
JOIN trade_order o ON o.order_id = r.order_id
WHERE

    r.buyer_id = #{userId}
    r.seller_id = #{userId}

AND r.status = #{status}
AND o.tenant_id = #{tenantId}
ORDER BY r.refund_id DESC

SELECT FROM trade_refund r JOIN trade_order o ON o.order_id = r.order_id WHERE 1 = 1 AND r.status = #{status}
AND ( (r.status = 'pending_seller' AND r.create_time < DATE_SUB(NOW(), INTERVAL 48 HOUR)) OR (r.status IN ('seller_agreed','buyer_returned') AND r.update_time < DATE_SUB(NOW(), INTERVAL 7 DAY)) OR (r.status IN ('mediation','refunding') AND r.update_time < DATE_SUB(NOW(), INTERVAL 24 HOUR)) )
AND o.tenant_id = #{tenantId} ORDER BY r.refund_id DESC

mapper.update:
UPDATE trade_refund
SET status = #{toStatus}, update_time = NOW()
WHERE refund_id = #{refundId}
  AND status = #{fromStatus}

UPDATE trade_refund
SET return_company = #{company}, return_no = #{returnNo}, update_time = NOW()
WHERE refund_id = #{refundId}

UPDATE trade_refund
SET return_address_snapshot = #{returnAddress}, update_time = NOW()
WHERE refund_id = #{refundId}

mapper.select:
SELECT 
FROM trade_refund r
WHERE r.status = 'pending_seller'
  AND r.create_time < #{before}
ORDER BY r.refund_id
LIMIT #{limit}

SELECT 
FROM trade_refund r
WHERE r.status = 'seller_agreed'
  AND r.create_time < #{before}
ORDER BY r.refund_id
LIMIT #{limit}

SELECT 
FROM trade_refund r
WHERE r.status = 'buyer_returned'
  AND r.update_time < #{before}
ORDER BY r.refund_id
LIMIT #{limit}
